```python
# Analyze market trends (example: using simple moving averages)
def calculate_sma(data, window):
    return data['close'].rolling(window=window).mean()

# Calculate SMA for each ticker
smas = {}
for ticker in current_holdings.keys():
    sma = calculate_sma(latest_quotes[latest_quotes['ticker'] == ticker], window=20)
    smas[ticker] = sma.iloc[-1]

# Determine the target weights based on SMA
target_weights = {}
for ticker, sma in smas.items():
    if sma > latest_quotes[latest_quotes['ticker'] == ticker]['close'].iloc[-1]:
        target_weights[ticker] = current_holdings[ticker] * 1.1  # Increase weight if SMA is above the current price
    else:
        target_weights[ticker] = current_holdings[ticker] * 0.9  # Decrease weight if SMA is below the current price

# Ensure the total weight does not exceed 1
total_weight = sum(target_weights.values())
if total_weight > 1:
    for ticker in target_weights:
        target_weights[ticker] /= total_weight

# Print the target weights
print("Target Weights:", target_weights)
```

